// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract MathHelper {
    function unsafeSubtract(uint256 a, uint256 b) external pure returns (uint256) {
        // TODO: retourneer a - b zónder de 0.8 overflow checks (bespaar gas)
    }
}

practice.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract MathHelper {
    function unsafeSubtract(uint256 a, uint256 b) external pure returns (uint256) {
        unchecked {
            return a - b;
        }
    }
}

