production.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract TariffCalculator {
    uint256 public constant MAX_FEE = 10000;
    uint256 public immutable baseFee;

    constructor(uint256 _baseFee) {
        baseFee = _baseFee;
    }

    function calculateTotal(uint256 amount, uint256 extraFee) external view returns (uint256) {
        return amount + baseFee + extraFee;
    }

    function getDiscountedFee(uint256 discount) external view returns (uint256) {
        return baseFee - discount;
    }

    function pay() external payable {
    }
}
